window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-8201\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γηροκομέω</h1><div class=\"entry-meta\"><span>DGP · ordem 287 na letra γ · nº geral 8201</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">γηροβοσκέω.</p></section></article>\n<article id=\"entry-dgp-8202\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γηροτροφέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 288 na letra γ · nº geral 8202</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. γηροτροφήσω) = γηροβοσκέω.</p></section></article>\n<article id=\"entry-dgp-8203\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γηροτροφία</h1><div class=\"entry-meta\"><span>DGP · ordem 289 na letra γ · nº geral 8203</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">γηροβοσκία.</p></section></article>\n<article id=\"entry-dgp-8204\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γηροτρόφος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 290 na letra γ · nº geral 8204</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">γηροβοσκός. 〈γῆρας, τρέφω〉</p></section></article>\n<article id=\"entry-dgp-8205\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γηροφορέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 291 na letra γ · nº geral 8205</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) transportar o pai idoso. 〈γῆρας, φέρω〉</p></section></article>\n<article id=\"entry-dgp-8206\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γήρυμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 292 na letra γ · nº geral 8206</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">voz; som. 〈γηρύω〉</p></section></article>\n<article id=\"entry-dgp-8207\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γῆρυς, υος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 293 na letra γ · nº geral 8207</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 voz 2 palavra 3 linguagem. 〈γηρύω〉</p></section></article>\n<article id=\"entry-dgp-8208\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γηρύω,</h1><div class=\"entry-meta\"><span>DGP · ordem 294 na letra γ · nº geral 8208</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. γαρύω at. e méd. 1 fazer ouvir; falar; proferir 2 celebrar; cantar ♦ méd. 3 cantar; competir: γαρύεσθαί τινι teócr. rivalizar no canto com alguém.</p></section></article>\n<article id=\"entry-dgp-8209\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Γηρυών, όνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 295 na letra γ · nº geral 8209</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Gerião, monstro de três cabeças ou corpos.</p></section></article>\n<article id=\"entry-dgp-8210\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γήρως</h1><div class=\"entry-meta\"><span>DGP · ordem 296 na letra γ · nº geral 8210</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. de γῆρας.</p></section></article>\n<article id=\"entry-dgp-8211\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γῄτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 297 na letra γ · nº geral 8211</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">γηΐτης.</p></section></article>\n<article id=\"entry-dgp-8212\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γιγάντειος</h1><div class=\"entry-meta\"><span>DGP · ordem 298 na letra γ · nº geral 8212</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e γιγαντιαῖος, α, ον de gigante; gigantesco. 〈γίγας〉</p></section></article>\n<article id=\"entry-dgp-8213\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γιγαντικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 299 na letra γ · nº geral 8213</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">γιγάντειος. 〈γίγας〉</p></section></article>\n<article id=\"entry-dgp-8214\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γιγαντολέτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 300 na letra γ · nº geral 8214</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">destruidor de gigantes, epít. de deuses. 〈γίγας, ὄλλυμι〉</p></section></article>\n<article id=\"entry-dgp-8215\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γιγαντολέτις, ιδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 301 na letra γ · nº geral 8215</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">destruidora de gigantes, epít. de Atena. 〈γίγας, ὄλλυμι〉</p></section></article>\n<article id=\"entry-dgp-8216\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γιγαντολέτωρ, ορος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 302 na letra γ · nº geral 8216</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">γιγαντολέτης.</p></section></article>\n<article id=\"entry-dgp-8217\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γιγαντομαχία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 303 na letra γ · nº geral 8217</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">combate dos gigantes; gigan­tomaquia. 〈γίγας, μάχη〉</p></section></article>\n<article id=\"entry-dgp-8218\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γίγαρτον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 304 na letra γ · nº geral 8218</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 semente de uva 2 pl. bagaço de uva.</p></section></article>\n<article id=\"entry-dgp-8219\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Γίγας, αντος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 305 na letra γ · nº geral 8219</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Gigante; pl. Gigantes, filhos de Urano e de Gaia 2 homem de tamanho extraordinário e vio­lento.</p></section></article>\n<article id=\"entry-dgp-8220\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γίγνομαι,</h1><div class=\"entry-meta\"><span>DGP · ordem 306 na letra γ · nº geral 8220</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. γίνομαι (fut. γενήσομαι, aor.2 ἐγενόμην, perf. γέγονα e γεγένημαι) 1 (pessoa) vir a ser; nascer; ser filho de 2 (planta) nascer; brotar; crescer 3 (sentimento, sensação, fato, fenômeno natural) ocorrer; produzir-se 4 (período de tempo) chegar; vir 5 tornar-se; aparecer como, com predic. do suj. (nome ou part.) 6 chegar a uma situação; comportar-se de determinado modo, adv. 7 tornar-se dependente de; estar sob o controle de, gen 8 tornar-se um dentre muitos; tornar-se parte de, gen. part. 9 alcançar; chegar a, gen. de preço 10 γίγνεσθαι com prep.: γ. ἀπό, sair de; γ. διά e gen. encontrar-se em; γ. ἐκ, desaparecer de; γ. ἐν, ἐπί e dat. ou gen., κατά e ac. chegar a; γ. μετά e gen. ou σύν e dat. associar-se a; γ. παρά e dat., tornar-se próximo de; γ. περί e ac. ocupar-se de; γ. πρός e ac. ou dat. aplicar-se a; γ. ὑπό e dat. cair sob o poder de 1 ἡμέρῃ τῇ ἐγένετο βασιλεύς her o dia em que o rei nasceu, οἱ ἐξ ἡμῶν γεγονότες isócr os que nasceram de nós 2 ὅσσα τε φύλλα καὶ ἄνθεα γίγνεται ὥρῃ hom. assim como se produzem folhas e flores na primavera, τὰ γιγνόμενα artt. a produção; os frutos; os rendimentos 3 σφιν ἄχος κατὰ θυμὸν ἐγίγνετο hom. veio-lhe ao coração uma dor, ἡ νόσος ἤρξατο γενέσθαι tuc. a doença começou a manifestar-se, πνεῦμα γίγνεται tuc. surge um vento, ἅμα δὲ ἕῳ γιγνομένῃ tuc. ao nascer do dia, τὸ γιγνόμενον o que acontece, τὸ γενόμενον o que aconteceu; o fato, τὸ γεγενεμένον o fato ocorrido; o passado, τὸ γενησόμενον o que vai acontecer; o futuro 4 ὡς τρίτη ἡμέρη ἐγένετο her. quando chegou o terceiro dia, πρὶν ἓξ μῆνας γεγονέναι plat. antes que seis meses tenham decorrido 5 πρευμενὴς δ᾽ ἡμῖν γενοῦ eur. torna-te favorável a nós, ὅταν ὁ ἥλιος αὖ πάλιν ἀπιὼν γένηται xen. quando o sol estiver se pondo de novo 6 γίγνεταί σοι κακῶς dem. [os negócios] vão mal para ti 7 οὐκέθ᾽ αὑτῶν γίγνονται plat. nunca mais estão sob o controle de si mesmos, ἢν ὑμῶν αὐτῶν ἐθελήσητε γενέσθαι dem. se quereis tornar-vos dependentes de vós mesmos 8 γενόμενος τῶν βασιληΐων δικαστέων her. tendo-se tornado um dos juízes reais, οὗτοι τῶν γεραιτέρων γίνονται xen. esses pertencem [à categoria] dos anciãos 9 ὁ σῖτος ἐγένετο ἑκκαίδεκα δραχμῶν dem. o trigo alcançou dezesseis dracmas, πολλοῦ ἀργυρίου γίγνεσθαι xen. custar muito dinheiro 10 τὸ ἀπὸ τῶν αἰχμαλώτων γιγνόμενον ἀργύριον xen. dinheiro proveniente da venda de prisioneiros, γίγνομαί σοι δι᾽ ἐχθρᾶς ar. indisponho-me contigo, γίγνεσθαι δι᾽ ὀργῆς plat. encolerizar-se, γ. ἐξ ἀνθρώπων paus. desaparecer do meio dos homens, οἳ ἐν δυνάμει γιγνόμενοι dem. os que alcançam o poder, γενόμενος ἐν αἰτίᾳ plat. tendo sido posto em causa, ἀκούσας ταῦτα ὁ Κλέαρχος ἐν ἑαυτῷ ἐγένετο xen. tendo ouvido essas coisas, Clearco tornou-se senhor de si próprio, γ. ἐπὶ ποταμῷ her. chegar ao rio, γίγνομαι ἐπὶ ταύτης τῆς γνώμης dem. sou dessa opinião, ἕως ἐγένοντο κατὰ τὸν γήλοφον xen. até que tivessem alcançado a elevação, γενέσθαι παρ᾽ ἀμφοτέροις τοῖς πράγμασι tuc. assistir aos acontecimentos em ambos os lados, εἰ περὶ τὸ συμβουλεύειν μόνον γενοίμην isócr. se eu me ativesse apenas em aconselhar, πρὸς αὑτῷ γενόμενος βραχὺν χρόνον plut. recolhendo-se a si mesmo um instante, γίγνονται πάλιν ὑπὸ Ῥωμαίοις plut. tornam a cair sob o domínio romano.</p></section></article>\n<article id=\"entry-dgp-8221\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γιγνώσκω</h1><div class=\"entry-meta\"><span>DGP · ordem 307 na letra γ · nº geral 8221</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐγίγνωσκον, fut. γνώσομαι, aor.2 ἔγνων, perf. ἔγνωκα, m.-q.-perf. ἐγνώκειν; pas. fut. γνωσθήσομαι, aor. ἐγνώσθην, perf. ἔγνωσμαι) ativa 1 conhecer 2 compreender; no perf. estar inteirado de; saber 3 reconhecer; distinguir, ac. ou gen. 4 formar uma opinião; pensar; julgar; decidir, ac. ou inf. 5 julgar; decretar; determinar, ac. e inf. 6 dar-se conta de; entender; aprender; saber, or. conj. (ὅτι, ὡς), inter. indir., part. (nom., gen., ac.) 7 tornar conhecido 8 tard. conhecer carnalmente; ter relações sexuais com, ac. passiva 9 ser conhecido ou reconhecido 10 Jur. ser reconhecido culpado 11 ser pronunciado 1 γνῶθι σαυτόν plat. conhece-te a ti mesmo, ὀλεῖς με, γιγνώσκω σε sóf. causarás minha ruína, conheço-te 2 νῦν ἔγνων τὸν Ἔρωτα teócr. agora eu compreendo o amor, οἱ ἐγνώκοτες plot. os que possuem a sabedoria 3 ὄφρ᾽ ἐῢ γιγνώσκῃς ἠμὲν θεὸν ἠδὲ καὶ ἄνδρα hom. a fim de que identifiques bem seja um homem, seja um deus, εἰ δ᾽ ἐτεὸν δὴ ἔστ᾽ Ὀδυσεὺς καὶ οἶκον ἱκάνεται, ἦ μάλα νῶι γνωσόμεθ᾽ ἀλλήλων hom. se realmente Odisseu está vivo e chega à sua casa, então nós nos reconheceremos um ao outro 4 περὶ τῆς βοηθείας ταῦτα γιγνώσκω dem. a respeito do socorro, penso isso, τὰ δίκαια γιγνώσκειν hes. tomar uma decisão justa, μάχης ἐγνωκὼς ἀπέχεσθαι plut. tendo decidido abster-se de batalha 5 Λακεδαιμόνιοι δὲ ἔγνωσαν περιυβρίσθαι Αἰγινήτας her. os lacedemônios decidiram que os eginetas foram ultrajados, ὁπόσοι τὸν μὲν θάνατον ἐγνώκασι πᾶσι κοινὸν εἶναι καὶ ἀναγκαῖον ἀνθρώποις xen. quantos julgaram que a morte é comum e necessária a todos os homens 6 παθὼν δέ τε νήπιος ἔγνω hes. o simplório aprende com o sofrimento, ἔγνω καὶ μάλα ἄτοπα ἐμοῦ ποιοῦντος xen. percebeu que eu fazia coisas muito estranhas, ἔγνων γάρ μιν ἐς ἄντα ἰδὼν οἰωνὸν ἐόντα hom. pois ao vê-lo diante de mim, compreendi que era um presságio, ἵνα γνῷ τρέφειν τὴν γλῶσσαν ἡσυχωτέραν sóf. para que aprenda a cultivar uma linguagem mais moderada, γιγνώσκονθ᾽ ὅτι τὸ τῆς ἀνάγκης ἔστ᾽ ἀδήριτον σθένος ésql. compreendendo que a força do destino é invencível, χαλεπόν ἐστι τὸ γνῶναι εἰ οἶδεν ἢ μή artt. é difícil saber se ele sabe ou não; no diálogo ἔγνων sóf. compreendi; sei, ἔγνως sóf. compreendeste, i.e., tens razão 7 γνώσομαι τὰν ὀλβίαν Κόρινθον pínd. celebrarei a opulenta Corinto 8 οὔτ᾽ ἄλλην ἔγνω γυναῖκα πρὸ γάμου plut. não conheceu outra mulher antes do casamento 9 γνωσθήσει ποτ᾽ Ἀθηναίοις οἷα διδάσκεις τοὺς ἀνοήτους ar. um dia os atenienses reconhecerão que tipo de ensinamento dás aos simplórios 10 ψήφῳ πόλεως γνωσθεῖσαι ésql. condenadas por um voto da cidade 11 ἡ ὑπὸ τῶν ἐχθρῶν ἐγνωσμένη κρίσις isócr. o julga­mento pronunciado pelos inimigos</p></section></article>\n<article id=\"entry-dgp-8222\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γίνομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 308 na letra γ · nº geral 8222</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = γίγνομαι.</p></section></article>\n<article id=\"entry-dgp-8223\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γινώσκω</h1><div class=\"entry-meta\"><span>DGP · ordem 309 na letra γ · nº geral 8223</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = γιγνώσκω.</p></section></article>\n<article id=\"entry-dgp-8224\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλάγος, εος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 310 na letra γ · nº geral 8224</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">poét. = γάλα.</p></section></article>\n<article id=\"entry-dgp-8225\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλακτοφάγος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 311 na letra γ · nº geral 8225</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que vive de leite. 〈γάλα, φαγεῖν〉</p></section></article>\n<article id=\"entry-dgp-8226\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλάμων, ωνος</h1><div class=\"entry-meta\"><span>DGP · ordem 312 na letra γ · nº geral 8226</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) remelento (olho).</p></section></article>\n<article id=\"entry-dgp-8227\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλαυκιάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 313 na letra γ · nº geral 8227</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) 1 ter aspecto cintilante 2 ter olhos brilhantes; ter olhos glaucos 3 ser acometido de glaucoma. 〈γλαυκός〉</p></section></article>\n<article id=\"entry-dgp-8228\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλαύκινος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 314 na letra γ · nº geral 8228</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cinza azulado. 〈γλαυκός〉</p></section></article>\n<article id=\"entry-dgp-8229\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλαυκιόων</h1><div class=\"entry-meta\"><span>DGP · ordem 315 na letra γ · nº geral 8229</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. pres. ép. de γλαυκιάω.</p></section></article>\n<article id=\"entry-dgp-8230\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλαυκόμματος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 316 na letra γ · nº geral 8230</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de olhos brilhantes; de olhos glaucos. 〈γλαυκός2, ὄμμα〉</p></section></article>\n<article id=\"entry-dgp-8231\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλαυκός1</h1><div class=\"entry-meta\"><span>DGP · ordem 317 na letra γ · nº geral 8231</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. de γλαύξ.</p></section></article>\n<article id=\"entry-dgp-8232\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλαυκός2, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 318 na letra γ · nº geral 8232</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que emite reflexos; brilhante; cintilante 2 glauco; verde-claro; cinza; esverdeado.</p></section></article>\n<article id=\"entry-dgp-8233\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλαυκότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 319 na letra γ · nº geral 8233</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cor glauca ou clara 2 brilho do olhar. 〈γλαυκός2〉</p></section></article>\n<article id=\"entry-dgp-8234\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλαυκῶπις, ιδος</h1><div class=\"entry-meta\"><span>DGP · ordem 320 na letra γ · nº geral 8234</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) 1 de olhos ou de cara de coruja, epít. de Atena 2 de olhos brilhantes; de olhos claros 3 brilhante (lua) 4 de cor verde-clara ou azul-clara. 〈γλαυκός2, ὤψ〉</p></section></article>\n<article id=\"entry-dgp-8235\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλαυκωπός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 321 na letra γ · nº geral 8235</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">γλαυκῶπις.</p></section></article>\n<article id=\"entry-dgp-8236\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλαύξ</h1><div class=\"entry-meta\"><span>DGP · ordem 322 na letra γ · nº geral 8236</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e γλαῦξ, gen. γλαυκός (ἡ) coruja: γλαῦκ᾽ Ἀθήναζε ou γλαῦκ᾽ εἰς Ἀθήνας prov. levar uma coruja a Atenas, onde havia muitas, i.e., levar areia para a praia.</p></section></article>\n<article id=\"entry-dgp-8237\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλαφυρία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 323 na letra γ · nº geral 8237</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 polimento 2 polidez de modos; graça; elegância (pessoa) 3 docilidade (costumes). 〈γλαφυρός〉</p></section></article>\n<article id=\"entry-dgp-8238\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλαφυρός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 324 na letra γ · nº geral 8238</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 oco; profundo; bem escavado 2 bem aplainado; bem polido 3 bem feito; elegante; refinado 4 engenhoso; hábil ♦ τὸ γλαφυρόν 5 polidez; urba­nidade. 〈γλάφω〉</p></section></article>\n<article id=\"entry-dgp-8239\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλαφυρότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 325 na letra γ · nº geral 8239</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fineza; polidez; elegância. 〈γλα­φυρός〉</p></section></article>\n<article id=\"entry-dgp-8240\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλαφυρῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 326 na letra γ · nº geral 8240</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 sutilmente 2 de maneira fina; delica­damente 3 habilmente.</p></section></article>\n<article id=\"entry-dgp-8241\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλεῦκος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 327 na letra γ · nº geral 8241</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 vinho doce 2 doçura.</p></section></article>\n<article id=\"entry-dgp-8242\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλήνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 328 na letra γ · nº geral 8242</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 menina do olho; pupila; olho 2 boneca; figura de boneca 3 cavidade onde se encaixa um osso.</p></section></article>\n<article id=\"entry-dgp-8243\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλῆνος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 329 na letra γ · nº geral 8243</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 menina do olho; pupila 2 objeto brilhante; jóia; enfeite. 〈γλήνη〉 χληχώ, οῦς e γλήχων, ωνος (ἡ) menta; hortelã.</p></section></article>\n<article id=\"entry-dgp-8244\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλίσχρος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 330 na letra γ · nº geral 8244</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 viscoso; pegajoso; aderente 2 fluido; escorregadio 3 tenaz; insistente 4 mesquinho; sórdido; pequeno. 〈γλίχομαι〉</p></section></article>\n<article id=\"entry-dgp-8245\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλισχρότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 331 na letra γ · nº geral 8245</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 viscosidade 2 mesquinharia; avareza; pequenez de espírito 3 chicana. 〈γλίσχρος〉</p></section></article>\n<article id=\"entry-dgp-8246\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλίσχρως</h1><div class=\"entry-meta\"><span>DGP · ordem 332 na letra γ · nº geral 8246</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 com viscosidade 2 tenazmente; com bastante cuidado 3 pobremente; sordidamente 4 com dificuldade; duramente.</p></section></article>\n<article id=\"entry-dgp-8247\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλίχομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 333 na letra γ · nº geral 8247</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres., impf. e aor. ἐγλιξάμην) desejar vivamente; querer muito algo, gen. ou περί e gen., or. com ὡς e fut. do ind. ou inf.</p></section></article>\n<article id=\"entry-dgp-8248\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλοιός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 334 na letra γ · nº geral 8248</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cola; goma 2 homem pegajoso; ho­mem repugnante.</p></section></article>\n<article id=\"entry-dgp-8249\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλουτός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 335 na letra γ · nº geral 8249</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">região glútea; traseiro; pl. nádegas.</p></section></article>\n<article id=\"entry-dgp-8250\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλυκαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 336 na letra γ · nº geral 8250</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. γλυκανῶ, aor. ἐγλύκανα, perf. desus.; pas. fut. γλυκανθήσομαι, aor. ἐγλυκάνθην, perf. γεγλύκασμαι) 1 tornar doce; adoçar 2 afetar com doçura, proporcionar sensação agradável a, ac.♦ méd. pas. 3 ser adoçado; tornar-se doce. 〈γλυκύς〉</p></section></article>\n<article id=\"entry-dgp-8251\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλυκεῖα</h1><div class=\"entry-meta\"><span>DGP · ordem 337 na letra γ · nº geral 8251</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. γλυκύς.</p></section></article>\n<article id=\"entry-dgp-8252\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλυκερός, ά, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 338 na letra γ · nº geral 8252</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">γλυκύς.</p></section></article>\n<article id=\"entry-dgp-8253\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλύκιστος, γλυκίων</h1><div class=\"entry-meta\"><span>DGP · ordem 339 na letra γ · nº geral 8253</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">superl. e comp. de γλυκύς.</p></section></article>\n<article id=\"entry-dgp-8254\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλυκυθυμία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 340 na letra γ · nº geral 8254</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 doçura de caráter; suavidade de temperamento; afabilidade 2 complacência; condes­cendência; indulgência. 〈γλυκύθυμος〉</p></section></article>\n<article id=\"entry-dgp-8255\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλυκύθυμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 341 na letra γ · nº geral 8255</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de caráter doce; de temperamento suave; afável 2 agradável; doce; aprazível. 〈γλυκύς, θυμός〉</p></section></article>\n<article id=\"entry-dgp-8256\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλυκύκαρπος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 342 na letra γ · nº geral 8256</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de doces frutos. 〈γλυκύς, καρπός〉</p></section></article>\n<article id=\"entry-dgp-8257\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλυκύμηλον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 343 na letra γ · nº geral 8257</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tipo de maçã bem doce. 〈γλυκύς, μῆλον〉</p></section></article>\n<article id=\"entry-dgp-8258\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλυκύπικρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 344 na letra γ · nº geral 8258</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">agridoce; doce-amargo. 〈γλυκύς, πικρός〉</p></section></article>\n<article id=\"entry-dgp-8259\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλυκύς, εῖα, ύ</h1><div class=\"entry-meta\"><span>DGP · ordem 345 na letra γ · nº geral 8259</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(comp. γλυκίων, át. γλυκύτερος; superl. γλύκιστος e γλυκύτατος) 1 doce (sabor) 2 doce (fra­grância) 3 doce; suave; agradável (coisas e pessoas): ὕπνου γλυκυτάτα χάρις eur. o dulcíssimo prazer do sono, γλυκεῖαι παῖδες ἀρχαίου Σκότου sóf. doces filhas da antiga Obscuridade, ὦ γλυκύτατε ar. ó caríssimo amigo! ὡς γλυκὺς εἶ plat. como és bom! ♦ ὁ γλυκύς e τὸ γλυκύ 4 vinho doce, feito de uvas secas ao sol ♦ ἡ γλυκεῖα 5 alcaçuz.</p></section></article>\n<article id=\"entry-dgp-8260\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλυκυσίδη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 346 na letra γ · nº geral 8260</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">peônia brilhante, planta. 〈γλυκύς〉</p></section></article>\n<article id=\"entry-dgp-8261\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλυκύτης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 347 na letra γ · nº geral 8261</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 doçura 2 doçura; suavidade; prazer 3 afeto 4 piedade. 〈γλυκύς〉</p></section></article>\n<article id=\"entry-dgp-8262\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλύφανος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 348 na letra γ · nº geral 8262</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cinzel de gravador ou de entalhador de pedra; buril 2 canivete. 〈γλύφω〉</p></section></article>\n<article id=\"entry-dgp-8263\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλυφεῖον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 349 na letra γ · nº geral 8263</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cinzel de escultor. 〈γλύφω〉</p></section></article>\n<article id=\"entry-dgp-8264\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλυφή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 350 na letra γ · nº geral 8264</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cinzeladura; gravura 2 emblema gravado. 〈γλύφω〉</p></section></article>\n<article id=\"entry-dgp-8265\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλυφίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 351 na letra γ · nº geral 8265</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 mossa de uma flecha 2 pl. entalhe na extremidade da flecha 3 flecha 4 tríglifo, ornamento do friso dório com três riscas verticais 5 cinzel do entalhador 6 canivete. 〈γλύφω〉</p></section></article>\n<article id=\"entry-dgp-8266\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλύφω</h1><div class=\"entry-meta\"><span>DGP · ordem 352 na letra γ · nº geral 8266</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἔγλυφον, fut. γλύψω, aor. ἔγλυψα, perf. desus.; pas. aor. ἐγλύφθην, aor.2 ἐγλύφην, perf. γέγλυμμαι e ἔγλυμμαι) 1 cinzelar; talhar; esculpir 2 gravar; gravar inscrição ♦ méd. 3 gravar ou mandar gravar para si.</p></section></article>\n<article id=\"entry-dgp-8267\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλῶσσα,</h1><div class=\"entry-meta\"><span>DGP · ordem 353 na letra γ · nº geral 8267</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. γλῶττα, ης (ἡ) 1 língua (órgão): ἀλλ᾽ ἄγε, τάμνετε μὲν γλώσσας κεράασθε δὲ οἶνον hom. mas vamos! Cortai as línguas (das vítimas) e misturai o vinho 2 língua; fala; voz: ἀπὸ γλώσσης her. de viva voz 3 expressão da fala; linguagem: γλώσσῃ θρασύς sóf. ousado em seu linguajar 4 língua particular; idioma; dialeto: γλῶσσαν δὲ οὐ τὴν αὐτὴν οὗτοι νενομίκασι, ἀλλὰ τρόπους τέσσερας παραγωγέων her. eles não usam o mesmo dialeto, mas quatro espécies de derivações 5 palavra estrangeira; empréstimo lingüístico; expressão inusitada que requer explicação: καὶ γλῶτταν καὶ κύριον εἶναι δυνατὸν τὸ αὐτό [ὄνομα] artt. uma mesma palavra pode ser um empréstimo e de uso corrente 6 objeto em forma de língua; língua ou lingüeta de instrumento de sopro, de sapato; língua de terra; lingote de ouro: γλῶσσαι ὡσεὶ πυρός n.t. como línguas de fogo, οὗ τὴν γλῶτταν ὥσπερ τῶν αὐλῶν ἐάν τις ἀφέλῃ, τὸ λοιπὸν οὐδέν ἐστιν ésql. se, como às flautas, alguém lhe tira a língua, o que resta é nada.</p></section></article>\n<article id=\"entry-dgp-8268\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλωσσαλγία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 354 na letra γ · nº geral 8268</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">coceira na língua; desejo ardente de falar; tagarelice. 〈γλῶσσα, ἀλγέω〉</p></section></article>\n<article id=\"entry-dgp-8269\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλωσσαργία,</h1><div class=\"entry-meta\"><span>DGP · ordem 355 na letra γ · nº geral 8269</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. γλωτταργία, ας (ἡ) inatividade da língua; taciturnidade; silêncio. 〈γλῶσσα, ἀργός〉</p></section></article>\n<article id=\"entry-dgp-8270\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλωσσίς,</h1><div class=\"entry-meta\"><span>DGP · ordem 356 na letra γ · nº geral 8270</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. γλωττίς, ίδος (ἡ) 1 lingüeta ou bocal de instrumento de sopro 2 glote; úvula palatina. 〈γλῶσσα〉</p></section></article>\n<article id=\"entry-dgp-8271\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλωσσόκομον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 357 na letra γ · nº geral 8271</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. 1 estojo para lingüetas de flauta 2 caixa; cofre de dinheiro. 〈γλῶσσα, κομέω〉</p></section></article>\n<article id=\"entry-dgp-8272\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλωσσοτομέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 358 na letra γ · nº geral 8272</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. γλωσσοτομήσω) 1 cortar a língua de alguém, ac. ♦ pas. 2 ter a língua cortada. 〈γλῶσσα, τόμος〉</p></section></article>\n<article id=\"entry-dgp-8273\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλῶττα, γλωτταρχία, γλωττίς</h1><div class=\"entry-meta\"><span>DGP · ordem 359 na letra γ · nº geral 8273</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. = γλῶσσα, γλωσσαρ­χία, γλωσσίς.</p></section></article>\n<article id=\"entry-dgp-8274\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γλωχίς</h1><div class=\"entry-meta\"><span>DGP · ordem 360 na letra γ · nº geral 8274</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e γλωχίν, ῖνος (ἡ) 1 qualquer extremidade pon­tuda 2 ponta 3 extremidade de terra.</p></section></article>\n<article id=\"entry-dgp-8275\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γναθμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 361 na letra γ · nº geral 8275</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">mandíbula de homem ou animal.</p></section></article>\n<article id=\"entry-dgp-8276\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γνάθος, ου (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 362 na letra γ · nº geral 8276</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 mandíbula 2 face; bochecha 3 boca.</p></section></article>\n<article id=\"entry-dgp-8277\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Γνάθων, ωνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 363 na letra γ · nº geral 8277</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Gnáton, nome de parasita em comédia. 〈γνάθος〉</p></section></article>\n<article id=\"entry-dgp-8278\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γναθώνειος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 364 na letra γ · nº geral 8278</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">digno de Gnáton, i.e., de um parasita. 〈Γνάθων〉</p></section></article>\n<article id=\"entry-dgp-8279\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Γναθωνίδης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 365 na letra γ · nº geral 8279</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">filho de Gnaton, i.e., filho de parasita. 〈Γνάθων〉</p></section></article>\n<article id=\"entry-dgp-8280\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γναμπτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 366 na letra γ · nº geral 8280</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 curvado; recurvado 2 que pode cur­var-se; macio; flexível. 〈γνάμπτω〉</p></section></article>\n<article id=\"entry-dgp-8281\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γνάμπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 367 na letra γ · nº geral 8281</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. γνάμψω, aor. ἔγναμψα, perf. desus.; pas. aor. ἐγνάμφθην) curvar; dobrar.</p></section></article>\n<article id=\"entry-dgp-8282\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γναφεύς, γναφεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 368 na letra γ · nº geral 8282</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">κναφεύς, κναφεύω.</p></section></article>\n<article id=\"entry-dgp-8283\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γνήσιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 369 na letra γ · nº geral 8283</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pertencente à raça; pertencente à família; de origem legítima: υἷε δύω Πριάμοιο, νόθος καὶ γνήσιος hom. dois filhos de Príamo, um bastardo e um legítimo, γνησίαι γυναῖκες xen. esposas legítimas 2 genuíno; autêntico; verda­deiro: γνήσιός εἰμι φίλος luc. sou amigo verdadeiro. 〈γένος〉</p></section></article>\n<article id=\"entry-dgp-8284\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γνησιότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 370 na letra γ · nº geral 8284</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 nascimento legítimo 2 origem nobre; nobreza. 〈γνήσιος〉</p></section></article>\n<article id=\"entry-dgp-8285\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γνησίως</h1><div class=\"entry-meta\"><span>DGP · ordem 371 na letra γ · nº geral 8285</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 mediante nascimento legítimo; legi­tima­mente 2 legitimamente; legalmente 3 verda­deira­mente; sinceramente; realmente.</p></section></article>\n<article id=\"entry-dgp-8286\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γνοῖεν, γνοίην</h1><div class=\"entry-meta\"><span>DGP · ordem 372 na letra γ · nº geral 8286</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. e 1a sing. do opt. aor.2 de γιγνώσκω.</p></section></article>\n<article id=\"entry-dgp-8287\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γνούς, γνόντος</h1><div class=\"entry-meta\"><span>DGP · ordem 373 na letra γ · nº geral 8287</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor.2 de γιγνώσκω.</p></section></article>\n<article id=\"entry-dgp-8288\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γνόφος, γνοφώδης</h1><div class=\"entry-meta\"><span>DGP · ordem 374 na letra γ · nº geral 8288</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">δνόφος, δνοφώδης.</p></section></article>\n<article id=\"entry-dgp-8289\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γνύξ</h1><div class=\"entry-meta\"><span>DGP · ordem 375 na letra γ · nº geral 8289</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de joelhos. 〈γόνυ〉</p></section></article>\n<article id=\"entry-dgp-8290\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γνῶ, γνῷς</h1><div class=\"entry-meta\"><span>DGP · ordem 376 na letra γ · nº geral 8290</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">etc. subj. aor.2 de γιγνώσκω.</p></section></article>\n<article id=\"entry-dgp-8291\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γνώης, γνώῃ</h1><div class=\"entry-meta\"><span>DGP · ordem 377 na letra γ · nº geral 8291</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª e 3ª sing. subj. aor.2 de γιγνώσκω.</p></section></article>\n<article id=\"entry-dgp-8292\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γνῶθι</h1><div class=\"entry-meta\"><span>DGP · ordem 378 na letra γ · nº geral 8292</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª sing. imper. aor.2 de γιγνώσκω.</p></section></article>\n<article id=\"entry-dgp-8293\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γνῶμα</h1><div class=\"entry-meta\"><span>DGP · ordem 379 na letra γ · nº geral 8293</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = γνώμη.</p></section></article>\n<article id=\"entry-dgp-8294\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γνῶμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 380 na letra γ · nº geral 8294</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sinal de identificação, partic. dente que marca a idade de um cavalo 2 prova 3 opinião. 〈γιγνώσκω〉</p></section></article>\n<article id=\"entry-dgp-8295\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γνωμέναι</h1><div class=\"entry-meta\"><span>DGP · ordem 381 na letra γ · nº geral 8295</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor. ép. de γιγνώσκω.</p></section></article>\n<article id=\"entry-dgp-8296\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γνώμη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 382 na letra γ · nº geral 8296</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 faculdade de conhecer e de julgar; inteligência; pensamento; razão; juízo: εἰ γνώμην ἔχεις xen. se tens juízo, τὸ μὲν ῥῆμα τῆς γλώττης ἁμάρτημά ἐστι, τὸ δὲ ἔργον τῆς γνώμης ant. com efeito a palavra é um erro da língua, o ato [um erro] do pensamento, γνώμῃ xen. com justa razão, οὐκ ἀπὸ γνώνης sóf. não sem julgamento; com bom senso, ἄτερ γνώμης ésql. sem bom senso; sem razão 2 meio de conhecer; marca; sinal: οὔτε κακῶν γνώμας εἰδότες, οὔτ᾽ ἀγαθῶν teóg. não tendo o conceito nem das coisas más nem das boas, λέγουσι γνώμην ἔχειν, ὅταν ἄβολος ᾖ teóg. dizem que tem uma marca quando não perdeu os dentes de leite 3 intenção; resolução; decisão: τήνδε ἔχω τὴν γνώμην her. esta é minha intenção, ἀπὸ γνώμης ἐκείνου dem. depois daquela decisão, γνώμην ποιοῦμαι θυγατέρα τὴν σὴν γῆμαι tuc. tomei a resolução de desposar tua filha, τίνα ἔχουσα γνώμην; her. com que intenção? 4 convicção; opinião: κατὰ γνώμην τὴν ἐμήν her. segundo minha opinião, ὁ αὐτός εἰμι τῇ γνώμῃ tuc. sou da mesma opinião, πλεῖστός εἰμι τῇ γνώμῃ tuc. eu me inclino para essa opinião, γνώμην τίθεσθαι, ἀποφάνειν manifestar uma opinião, μιᾷ γνώμῃ tuc. ou διὰ μιᾶς γνώμης isócr. por unanimidade, ὅσοι τῆς αὐτῆς γνώμης ἦσαν dem. todos os que fossem da mesma opinião 5 proposta; moção: γνώμην εἰσφέρειν her. apresentar uma proposta 6 disposição de espírito; ânimo; vontade: γνώμῃ τῇ δικαιοτάτῃ δικάσειν ὀμωμόκασιν dem. juraram julgar com disposição de eqüidade, i.e., com a máxima eqüidade, ἀμήχανον δὲ παντὸς ἀνδρὸς ἐκμαθεῖν ψυχήν τε καὶ φρόνημα καὶ γνώμην sóf. não há como conhecer a fundo a alma, os sentimentos e a vontade de cada homem, τὴν γνώμην ἔχειν πρός τι tuc. ter disposições favoráveis para algo; inclinar-se para algo, ἐν γνώμῃ γεγονέναι τινί her. cair nas graças de alguém, γνώμην τινὸς ἐμπιπλάναι ou ἐκπιμπλάναι xen. realizar a vontade de alguém, ἀφ᾽ ἑαυτοῦ γνώμης tuc. por sua própria vontade; espontaneamente 7 sentença de expressão breve; máxima: παῖδες ὄντες τὰς τῶν ποιητῶν γνώμας ἐκμανθάνομεν ésqn. sendo crianças, aprendemos pelas sentenças dos poetas.</p></section></article>\n<article id=\"entry-dgp-8297\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γνωμίδιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 383 na letra γ · nº geral 8297</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sentença curta. 〈γνώμων〉</p></section></article>\n<article id=\"entry-dgp-8298\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γνωμολογέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 384 na letra γ · nº geral 8298</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">falar através de máximas ou sentenças. 〈γνώμη, λόγος〉</p></section></article>\n<article id=\"entry-dgp-8299\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γνωμολογία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 385 na letra γ · nº geral 8299</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 expressão por meio de sentenças; estilo sentencioso 2 coleção de sentenças. 〈γνώμη, λόγος〉</p></section></article>\n<article id=\"entry-dgp-8300\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">γνωμονικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 386 na letra γ · nº geral 8300</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 capaz de discernir bem; capaz de julgar bem, gen. 2 hábil; perito em algo, gen. 3 relativo aos quadrantes solares. 〈γνώμων〉</p></section></article>";
